def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # Count recent behavior
    last = op[-1]
    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in my if x == 'C')
    my_d = n - my_c

    # Immediate retaliation against last defection, but with forgiveness
    if last == 'D':
        # If opponent has mostly cooperated, sometimes forgive
        if opp_d <= 2 and n >= 4:
            return 'C'
        return 'D'

    # If we defected last and opponent still cooperated, exploit a bit
    if my[-1] == 'D' and last == 'C':
        # But avoid excessive exploitation late
        if n < 80:
            return 'D'
        return 'C'

    # Early cooperation
    if n < 3:
        return 'C'

    # Detect possible always-defect or mostly-defect opponents
    if n >= 5:
        if opp_d >= n - 2:
            # Nearly always defects: defect, but occasionally test cooperation
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if opp_c >= n - 1:
            # Nearly always cooperates: exploit mildly
            if n < 90:
                return 'D'
            return 'C'

    # Tolerant tit-for-tat with occasional cooperation to rebuild
    if last == 'C':
        # Mostly cooperate, but occasionally probe
        if n > 60 and opp_d > 0:
            if rng.random() < 0.1:
                return 'D'
        return 'C'
    return 'D'
